import os, json
from mlib import *
def pcb(b):
    p = os.path.join(ROOT, "utility10/pcb/release", b, "5_verification", "readiness.json")
    if not os.path.exists(p): return "no released board"
    r = json.load(open(p)); return "**order-ready**" if r["order_ready"] else "not order-ready"
ROWS = [
 ("Utility tools", [("Seeti Counter", "utility10/01-seeti-counter", "seeti", "firmware compiled, not run on hardware"), ("Gas Taraju (LPG cylinder scale)", "utility10/02-gas-taraju", "gastaraju", "load-cell calibration per unit"), ("Fridge Door Guard", "utility10/03-fridge-door-guard", "fridge", ""), ("Bijli Meter Reader", "utility10/04-bijli-meter-reader", "bijli", ""), ("Bijli Log", "utility10/05-bijli-log", "bijlilog", "OLED/RTC drivers untested"), ("Chulha Timers", "utility10/06-chulha-timers", "chulha", "display driver untested"), ("Rain Alert Bell + plate", "utility10/07-rain-alert", "rain", "plate: `rainplate` board"), ("Tap Litre Meter", "utility10/08-tap-litre-meter", "tap", "needs bucket calibration"), ("Masala Rack (laser-cut)", "utility10/09-masala-rack", None, "kerf coupon first"), ("Laptop Stand (laser-cut)", "utility10/10-laptop-stand", None, "stability limit stated")]),
 ("Products", [("1 Desi Games Studio (print)", "products/01-desi-games", None, "language + fact review before print"), ("2 Kalakriti Automata (laser)", "products/02-automata", None, "frame layouts provisional"), ("3 Prayog STEM lab kit", "products/03-prayog", "prayog", "sensors uncalibrated"), ("4 Jal-Rakshak tank controller", "products/04-jal-rakshak", None, "**mains version cannot be made**: low-voltage prototype only"), ("5 Kheti-Mitra irrigation", "products/05-kheti-mitra", "kheti", "field trial required"), ("6 Gas-Suraksha leak alarm", "products/06-gas-suraksha", None, "**not certified, not for sale**")]),
 ("Toys (10)", [("01 Reflex Raja", "toys10/01-reflex-raja", "arcade", "shares the Desi Arcade board"), ("02 Taal Memory", "toys10/02-taal-memory", "arcade", "shares the Desi Arcade board"), ("03 Aloo Bomb", "toys10/03-aloo-bomb", "arcade", "shares the Desi Arcade board"), ("04 Beat Runner", "toys10/04-beat-runner", "beatrunner", ""), ("05 Rangoli Spiro Gears", "toys10/05-rangoli-spiro", None, "kerf test first"), ("06 Paper Rocket Launcher", "toys10/06-paper-rocket", None, "projectile toy: lab review before sale; no drawings"), ("07 Tilt Maze", "toys10/07-tilt-maze", None, "gimbal frame drawing missing"), ("08 Rubber-band Racer", "toys10/08-band-racer", None, "provisional cut file"), ("09 Marble Cricket", "toys10/09-marble-cricket", None, "provisional cut file; calibration drop"), ("10 Katha Cubes", "toys10/10-katha-cubes", None, "illustrations and proofreading missing")]),
 ("Other projects", [("Jal-Netra (engineering marvel)", "jal-netra", "jalnetra", "**Gate 1 acoustic test first; not sellable**"), ("Gravity toys (5)", "gravity-toys", None, "drawings partial"), ("Wave 1 electronics toys", "electronics-toys/wave1", None, "no PCB: not manufacturable yet"), ("Prototype packs (10)", "prototypes", None, "bench prototypes"), ("DJ / party system", "dj-setup", None, "plan only: not manufacturable")]),
]
L = ["# Manufacturing manuals: index", "", "Start with **[STANDARD_PROCEDURES.md](STANDARD_PROCEDURES.md)** (PCB ordering, SMT/THT assembly, soldering, programming, 3D printing, laser cutting, QA, packaging, compliance, troubleshooting) and the [templates](templates/). Each product has a `MANUFACTURING_MANUAL.md` with its bill of materials, build steps, calibration, end-of-line test and limits.", "",
     "**Honest status:** nothing in this repository has been built, assembled or tested as hardware. 'Order-ready' means the automatic checks pass (KiCad DRC 0 errors, schematic equals layout, every part has a verified LCSC number, Gerber/BOM/CPL consistent): it does **not** mean an engineer has reviewed the layout. Treat the first batch as a prototype run.", ""]
for grp, rows in ROWS:
    L += [f"## {grp}", "", "| Project | Manual | Board | Main caveat |", "|---|---|---|---|"]
    for name, path, board, cav in rows:
        L += [f"| {name} | [{path}/MANUFACTURING_MANUAL.md](../{path}/MANUFACTURING_MANUAL.md) | {pcb(board) if board else 'no PCB'} | {cav} |"]
    L += [""]
open(os.path.join(ROOT, "manuals", "README.md"), "w").write("\n".join(L)); print("index written")
